#ifndef COOLPROP_CUBIC_CONSTANTS_H
#define COOLPROP_CUBIC_CONSTANTS_H

// The critical-point constants of the SRK and Peng-Robinson equations of state, each the correctly
// rounded double of its closed form (Bell and Deiters, Ind. Eng. Chem. Res., 2021).  GENERATED by
// dev/scripts/cubic_constants.py (60-digit arithmetic); do not edit by hand -- `--check` verifies this
// file.  #2745 transcribed them as decimal digits with doubled and dropped digits, which put SRK's own
// critical point ~1e-9 below the input Tc and pc.  The test "Cubic Omega constants reproduce the
// critical point" checks the defining property.

namespace CoolProp {
namespace CubicConstants {

/// SRK: Omega_a = 1/(9 (2^(1/3) - 1)) = 0.42748023354034140439...
constexpr double SRK_Omega_a() {
    return 0x1.b5bd60daf8059p-2;
}

/// SRK: Omega_b = (2^(1/3) - 1)/3 = 0.08664034996495772158...
constexpr double SRK_Omega_b() {
    return 0x1.62e0fdd9d0d8fp-4;
}

/// SRK: Z_c = 1/3 exactly.
constexpr double SRK_Zc() {
    return 1.0 / 3.0;
}

/// Peng-Robinson: Omega_a = 0.45723552892138218938...
constexpr double PR_Omega_a() {
    return 0x1.d4358ced257a2p-2;
}

/// Peng-Robinson: Omega_b = 0.07779607390388845597...
constexpr double PR_Omega_b() {
    return 0x1.3ea71892ca57ap-4;
}

/// Peng-Robinson: Z_c = 0.30740130869870384800...
constexpr double PR_Zc() {
    return 0x1.3ac7689e6f236p-2;
}

}  // namespace CubicConstants
}  // namespace CoolProp

#endif
